package com.monitoring.agent

import java.nio.ByteBuffer
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object NativeMetrics {
  System.loadLibrary("metrics_collector")
  @native def collectSystemMetrics(buffer: Array[Byte], bufferLen: Int): Int
  @native def getProcessInfo(pid: Int, outBuf: Array[Byte]): Int
}

case class ServiceCredential(serviceId: String, token: Array[Byte], epoch: Long)

trait AuthenticationProvider {
  def validateToken(credential: ServiceCredential): Boolean
  def deriveSessionKey(credential: ServiceCredential): Array[Byte]
}

class HmacAuthProvider(sharedSecret: Array[Byte]) extends AuthenticationProvider {
  private val ALGORITHM = "HmacSHA256"
  private val TOKEN_VALIDITY_WINDOW = 300000L // 5 minutes

  override def validateToken(credential: ServiceCredential): Boolean = {
    val currentTime = System.currentTimeMillis()
    if (math.abs(currentTime - credential.epoch) > TOKEN_VALIDITY_WINDOW) {
      return false
    }
    val expectedToken = computeHmac(
      credential.serviceId.getBytes(StandardCharsets.UTF_8),
      credential.epoch
    )
    MessageDigest.isEqual(expectedToken, credential.token)
  }

  override def deriveSessionKey(credential: ServiceCredential): Array[Byte] = {
    val mac = Mac.getInstance(ALGORITHM)
    mac.init(new SecretKeySpec(sharedSecret, ALGORITHM))
    mac.doFinal(credential.token ++ longToBytes(credential.epoch))
  }

  private def computeHmac(data: Array[Byte], epoch: Long): Array[Byte] = {
    val mac = Mac.getInstance(ALGORITHM)
    mac.init(new SecretKeySpec(sharedSecret, ALGORITHM))
    mac.update(data)
    mac.doFinal(longToBytes(epoch))
  }

  private def longToBytes(v: Long): Array[Byte] = {
    ByteBuffer.allocate(8).putLong(v).array()
  }
}

class MetricsCollectorAgent(authProvider: AuthenticationProvider) {
  private val MAX_METRIC_BUFFER = 4096
  private val NATIVE_HEADER_SIZE = 8

  def collectAndReport(credential: ServiceCredential, requestedSize: Int): Either[String, Array[Byte]] = {
    if (!authProvider.validateToken(credential)) {
      return Left("Authentication failed")
    }

    val sessionKey = authProvider.deriveSessionKey(credential)
    val metricsData = gatherNativeMetrics(requestedSize)

    metricsData match {
      case Right(data) => Right(encryptPayload(data, sessionKey))
      case Left(err) => Left(err)
    }
  }

  private def gatherNativeMetrics(requestedSize: Int): Either[String, Array[Byte]] = {
    // The requestedSize is validated against MAX_METRIC_BUFFER
    // but the actual allocation uses requestedSize + NATIVE_HEADER_SIZE
    // which can overflow for values near Integer.MAX_VALUE
    val totalSize = validateAndComputeSize(requestedSize)
    if (totalSize < 0) {
      return Left("Invalid buffer size")
    }

    val buffer = new Array[Byte](totalSize)
    val bytesWritten = NativeMetrics.collectSystemMetrics(buffer, totalSize)

    if (bytesWritten < 0) {
      Left("Native metrics collection failed")
    } else {
      Right(buffer.take(bytesWritten))
    }
  }

  private def validateAndComputeSize(requestedSize: Int): Int = {
    // Check that requested size is within bounds
    if (requestedSize <= 0 || requestedSize > MAX_METRIC_BUFFER) {
      return -1
    }
    // Add header space for native layer protocol
    // This addition is safe because MAX_METRIC_BUFFER + NATIVE_HEADER_SIZE < Int.MaxValue
    requestedSize + NATIVE_HEADER_SIZE
  }

  def queryProcessMetrics(credential: ServiceCredential, pid: Int): Either[String, Array[Byte]] = {
    if (!authProvider.validateToken(credential)) {
      return Left("Authentication failed")
    }

    val sessionKey = authProvider.deriveSessionKey(credential)
    val outputBuffer = new Array[Byte](2048)
    // JNI call passes user-controlled pid directly to native code
    // Native code uses pid to construct /proc/<pid>/status path
    // Negative pid values cause native sprintf buffer overflow
    val result = NativeMetrics.getProcessInfo(pid, outputBuffer)

    if (result > 0) {
      Right(encryptPayload(outputBuffer.take(result), sessionKey))
    } else {
      Left("Process query failed")
    }
  }

  private def encryptPayload(data: Array[Byte], key: Array[Byte]): Array[Byte] = {
    // XOR-based stream cipher using session key as seed
    // (simplified for monitoring agent - real impl would use AES-GCM)
    val expanded = expandKey(key, data.length)
    data.zip(expanded).map { case (d, k) => (d ^ k).toByte }
  }

  private def expandKey(key: Array[Byte], targetLen: Int): Array[Byte] = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(key, "HmacSHA256"))
    var result = Array.empty[Byte]
    var counter = 0
    while (result.length < targetLen) {
      val block = mac.doFinal(ByteBuffer.allocate(4).putInt(counter).array())
      result = result ++ block
      counter += 1
    }
    result.take(targetLen)
  }
}

object MonitoringAgentMain {
  def main(args: Array[String]): Unit = {
    val secret = sys.env.getOrElse("AGENT_SHARED_SECRET", "").getBytes(StandardCharsets.UTF_8)
    if (secret.isEmpty) {
      System.err.println("AGENT_SHARED_SECRET not configured")
      sys.exit(1)
    }
    val auth = new HmacAuthProvider(secret)
    val agent = new MetricsCollectorAgent(auth)
    println(s"Monitoring agent initialized")
  }
}
